class Solution {
    /**
     * Given an integer n, return true if it is a power of three. Otherwise, return false.
     * An integer n is a power of three, if there exists an integer x such that n == 3^x.
     *
     * Example 1:
     * In: n = 27
     * Out: true
     * Explanation: 27 = 3^3
     *
     * Example 2:
     * In: n = 0
     * Out: false
     * Explanation: There is no x where 3^x = 0.
     *
     * Example 3:
     * In: n = -1
     * Out: false
     * Explanation: There is no x where 3x = (-1).
     *
     * Constraints:
     * -231 <= n <= 231 - 1
     *
     * @param n The integer to check.
     * @return True if n is a power of three, false otherwise.
     */
    public boolean isPowerOfThree(int n) {
        // If n is not positive, it cannot be a power of three.
        if (n <= 0) {
            return false;
        }

        // We can check if n is a power of three by repeatedly dividing it by 3 until it becomes 1.
        // If at any point, the division results in a non-integer, then n is not a power of three.
        // Alternatively, we can use logarithms.  However, the problem constraints limit the range of n,
        // so we can use a more efficient bitwise operation.

        // A number is a power of 3 if and only if s & (s - 1) == 0, where s is the number.
        // This works because powers of 3 have only one bit set to 1 in their binary representation.
        // Subtracting 1 from a power of 3 will result in a number with all bits set to 1 up to the position of the original 1.
        // The bitwise AND of these two numbers will be 0.

        return (n & (n - 1)) == 0;
    }
}
